pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, bytes memory data) public {
        amount = bound(amount, 0, 1 ether);
        Helper helper = new Helper();
        vm.deal(address(this), 2 ether);
        vm.deal(address(c), 1 ether);
        vm.prank(address(this));
        c.Command{value: amount}(address(helper), data);
        assertTrue(helper.received() == amount);
    }
}

contract Helper {
    uint256 public received;
    receive() external payable {
        received = msg.value;
    }
    fallback() external payable {
        received = msg.value;
    }
}
